// Everything here is ORIGINAL: invented titles and artists, lyrics written for this file, covers generated by lib/artwork.
// The genre tags are the kind of tags a service attaches to an artist; they stand in for real metadata so the pipeline can be
// exercised end to end. These are NOT real songs and the gallery says so.

import type { ArtStyle } from '../artwork/generate';
import type { GenreTag } from '../identity/types';

export type Fixture = {
  id: string;
  title: string;
  artist: string;
  blurb: string;
  tags: string[];
  year?: number;
  cover: { palette: [string, string, string, string]; style: ArtStyle };
  /** seconds into the song at which the gallery freezes the frame */
  at: number;
  lrc: string;
};

const tagsOf = (f: Fixture): GenreTag[] => f.tags.map((tag) => ({ tag, weight: 0.85, source: 'spotify' }));
export { tagsOf };

